import {ROLES,AREAS,allowed,permissionLabel,money,activeStatus,seed,freeUnits,mutate,migrate,itemsOf,unitsOf,OUT_CONDITIONS,IN_CONDITIONS,severe,assigned,balance,paymentHistory} from './core.js';
import {downloadMovement,movementDownload} from './movement-pdf.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{data=migrate(JSON.parse(localStorage.getItem('ponpon-demo-v1')))}catch{data=seed()}
let role=sessionStorage.getItem('ponpon-role')||'Administrador',route=location.hash.slice(1)||'inicio',search='',category='Todos',modalType='',modalId='',toastTimer,quoteDraft=[],inspectionDraft=[],productImage='',inventoryFilter='active',documentUrl='';
if(!ROLES.includes(role))role='';
const paths={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',sparkles:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H5v20h14V7Z M14 2v6h5 M8 12h8 M8 16h6',calendar:'M3 5h18v16H3Z M16 3v4 M8 3v4 M3 10h18 M7 14h3 M14 14h3 M7 17h3',box:'m12 2 9 5v10l-9 5-9-5V7Z M3 7l9 5 9-5 M12 12v10 M7.5 4.5l9 5',clipboard:'M9 4H5v18h14V4h-4 M9 2h6v5H9Z M8 12h8 M8 16h6',out:'M14 3H3v18h11 M9 12h13 M17 7l5 5-5 5',in:'M14 3H3v18h11 M22 12H9 M14 7l-5 5 5 5',alert:'m12 3 10 18H2Z M12 9v5 M12 17h.01',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z m-4 10 3 3 5-6',chart:'M4 3v18h18 M8 16v-4 M13 16V8 M18 16V5',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',key:'M14 6a5 5 0 1 1-7 7l-5 5v4h4v-3h3l3-3 M15 7h.01',lock:'M5 10h14v12H5Z M8 10V6a4 4 0 0 1 8 0v4',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',menu:'M3 6h18 M3 12h18 M3 18h18',logout:'M9 3H3v18h6 M10 12h12 M17 7l5 5-5 5',smile:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M8 14c1 5 7 5 8 0 M8 8h.01 M16 8h.01',refresh:'M21 3v6h-6 M3 21v-6h6 M20 9a9 9 0 0 0-16-3 M4 15a9 9 0 0 0 16 3'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.sparkles}"/></svg>`;
const btn=(label,action,style='primary',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(text,color='green')=>`<span class="badge ${color} dot">${esc(text)}</span>`;
const status=q=>({COTIZACION:['Cotización','gray'],CONFIRMADA:['Confirmada','green'],EN_PREPARACION:['En preparación','orange'],DESPACHADA:['Despachada','blue'],FINALIZADA:['Finalizada','gray']}[q.status]||[q.status,'gray']);
const qBadge=q=>badge(...status(q));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('es-HN',{day:'2-digit',month:'short'});
const product=id=>data.products.find(x=>x.id===id)||{},client=id=>data.clients.find(x=>x.id===id)||{};
const save=()=>localStorage.setItem('ponpon-demo-v1',JSON.stringify(data));
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function go(area){if(route===area){render();return}location.hash=area}
function setRole(next){if(!ROLES.includes(next))return;role=next;sessionStorage.setItem('ponpon-role',role);$('#modal').close();render();toast('Modo de prueba: '+role+'. Los permisos se han actualizado.')}
function run(action,payload){const previous=structuredClone(data);try{const r=mutate(data,role,action,payload);if(action==='reset')data=r;save();return r}catch(error){data=previous;throw error}}
function artwork(type){const defs='<defs><linearGradient id="sh" x2="0" y2="1"><stop stop-color="#fff" stop-opacity=".3"/><stop offset="1" stop-color="#000" stop-opacity=".05"/></linearGradient></defs>';let body='';
 if(type==='castle')body='<rect x="35" y="65" width="130" height="65" rx="9" fill="#e4b46a"/><path d="M28 66h144v12H28" fill="#d59a50"/><rect x="25" y="35" width="35" height="95" rx="6" fill="#88a78c"/><rect x="140" y="35" width="35" height="95" rx="6" fill="#88a78c"/><path d="M22 38 42 13 63 38Z M137 38l20-25 21 25Z" fill="#d48d70"/><rect x="83" y="89" width="34" height="41" rx="17" fill="#547a68"/><path d="M62 66V52h19v14m19 0V52h19v14m19 0V52h-4" fill="#e4b46a"/><rect x="21" y="127" width="158" height="9" rx="4" fill="#bbd0a9"/>';
 else if(type==='slide')body='<path d="M34 132V48q0-10 12-10h55v94" fill="#dfb36d"/><path d="M88 39h18v18c0 35 13 56 61 56v20c-59 0-79-31-79-76Z" fill="#83a18c"/><path d="M105 44h13c0 29 7 52 54 53v17c-52-1-67-26-67-59Z" fill="#d88f73"/><rect x="45" y="59" width="26" height="74" rx="3" fill="#759b83"/><path d="M46 74h24M46 90h24M46 106h24M46 122h24" stroke="#f2d6a5" stroke-width="5"/><path d="m30 39 37-25 39 25" fill="#d48d70"/>';
 else if(type==='table')body='<path d="M52 82v43M139 82v43" stroke="#bd9b6e" stroke-width="8"/><rect x="39" y="64" width="113" height="22" rx="10" fill="#dcb474"/><path d="M23 106v25m31-25v25m95-25v25m30-25v25" stroke="#7a9c85" stroke-width="6"/><rect x="15" y="96" width="47" height="14" rx="5" fill="#a4b89b"/><rect x="141" y="96" width="47" height="14" rx="5" fill="#a4b89b"/><rect x="18" y="68" width="12" height="38" rx="5" fill="#85a48c"/><rect x="173" y="68" width="12" height="38" rx="5" fill="#85a48c"/>';
 else if(type==='pool')body='<ellipse cx="100" cy="94" rx="80" ry="36" fill="#8da79e"/><path d="M20 94v20c0 46 160 46 160 0V94" fill="#e3b983"/><ellipse cx="100" cy="90" rx="77" ry="30" fill="#abc2ad"/>'+Array.from({length:20},(_,i)=>`<circle cx="${43+(i%6)*23+(i%2)*3}" cy="${76+Math.floor(i/6)*13}" r="7" fill="${['#d88f73','#eed5a6','#7d9e8a','#c6b3a4'][i%4]}"/>`).join('')+'<ellipse cx="100" cy="92" rx="79" ry="32" stroke="#e5bf8d" stroke-width="9" fill="none"/>';
 else if(type==='arch')body='<path d="M40 135V68a60 60 0 0 1 120 0v67" fill="none" stroke="#d4aa75" stroke-width="7"/>'+Array.from({length:13},(_,i)=>{const a=Math.PI+i*Math.PI/12;return `<ellipse cx="${100+60*Math.cos(a)}" cy="${77+59*Math.sin(a)}" rx="16" ry="19" fill="${['#d6a17f','#afbe9c','#e5cfa5'][i%3]}"/>`}).join('')+'<rect x="78" y="55" width="44" height="38" rx="6" fill="#f6f0de"/><path d="m87 75 8 6 15-15" stroke="#a9b793" stroke-width="3" fill="none"/>';
 else body='<circle cx="99" cy="56" r="23" fill="#e5b58a"/><path d="M72 54q4-38 32-24 24-1 20 30l-8-14-22-3-21 13" fill="#725e49"/><path d="M66 133V99q0-24 34-24t34 24v34" fill="#96ae8f"/><path d="m75 97-26 21M126 97l26 21" stroke="#e5b58a" stroke-width="11" stroke-linecap="round"/><path d="m143 37 8-19 13 23Z" fill="#d99a78"/><circle cx="55" cy="38" r="13" fill="#dbbc80"/><path d="M55 51q-7 15 0 27" stroke="#a28b6d" fill="none"/>';
 return `<svg viewBox="0 0 200 150" aria-hidden="true">${defs}<ellipse cx="100" cy="137" rx="87" ry="7" fill="#334e3610"/>${body}</svg>`}
function nav(){let group='';$('#sidebar').innerHTML=`<a class="brand" href="#inicio"><span class="brandmark">✳</span><span><small>EL CLUB DE</small>Pon Pon<span style="color:#f2bf87">.</span></span></a>`+AREAS.map(([id,name,ic,g])=>{const h=group!==g?`<div class="nav-group">${g}</div>`:'';group=g;return h+`<a href="#${id}" class="nav ${route===id?'active':''} ${!allowed(role,id)?'blocked':''}" ${route===id?'aria-current="page"':''} aria-label="${name}${!allowed(role,id)?' · acceso restringido':''}">${icon(ic)}<span>${name}</span>${!allowed(role,id)?icon('lock').replace('<svg','<svg class="lock"'):''}</a>`}).join('')+`<div class="sidebar-bottom"><div class="help-card"><strong style="font-size:11px">Tu equipo, en sintonía.</strong><p>Cambia de rol y explora cómo trabaja cada área.</p><a href="#permisos">Probar los permisos ${icon('arrow')}</a></div><div class="side-foot">PROTOTIPO INTERACTIVO · V2.0</div></div>`}
function header(){const area=AREAS.find(x=>x[0]===route);$('#topbar').innerHTML=`<button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir navegación">${icon('menu')}</button><div class="breadcrumb">Espacio de trabajo <span>/</span><strong>${esc(area?.[1]||'Acceso')}</strong></div><div class="top-right"><span class="private">${icon('lock')} Acceso privado</span><button class="icon-button" data-action="activity" aria-label="Ver actividad reciente">${icon('bell')}</button><div class="role-control"><span class="avatar">${role==='Administrador'?'AD':role==='Ventas'?'VE':'LO'}</span><div><label for="role">Simular rol</label><select id="role" aria-label="Cambiar rol">${ROLES.map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select></div></div><button class="icon-button" data-action="logout" aria-label="Cerrar sesión de prueba">${icon('logout')}</button></div>`}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${route==='inicio'?'TU ESPACIO DE TRABAJO':'EL CLUB DE PON PON'}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function stat(label,value,sub,ic){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-bottom">${sub}</div></div>`}
function notice(text,kind=''){return `<div class="notice ${kind}">${icon(kind==='demo'?'sparkles':'shield')}<span>${text}</span></div>`}
function eventRow(q){return `<tr><td><div class="event-name"><span class="event-dot">✳</span><div><strong>${esc(q.title)}</strong><small>${esc(client(q.clientId).name)}</small></div></div></td><td><strong>${date(q.date)}</strong><small>${q.start} – ${q.end}</small></td><td>${qBadge(q)}</td><td><button class="btn ghost small" data-action="detail" data-id="${q.id}" aria-label="Ver ${esc(q.title)}">${icon('arrow')}</button></td></tr>`}
function dashboard(){const events=data.quotes.filter(x=>activeStatus(x.status)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),next=events[0],inventory=data.products.filter(p=>p.active).reduce((a,p)=>a+p.stock-p.maintenance,0),repair=data.products.reduce((a,p)=>a+p.maintenance,0),sales=role!=='Logística';return heading('Un buen día para celebrar.','Todo lo que tu equipo necesita, en un mismo lugar.',sales?btn(icon('plus')+' Nueva cotización','new-quote'):btn(icon('clipboard')+' Ver hojas de eventos','nav','primary','data-to="hojas"'))+
 `<section class="hero"><div><div class="eyebrow">PEQUEÑOS DETALLES, GRANDES MOMENTOS</div><h2>Detrás de cada sonrisa,<br>un equipo organizado.</h2><p>Conecta las ideas de Ventas con el trabajo de Logística y haz que cada evento suceda.</p><a class="btn small" href="#${sales?'reservas':'hojas'}">${sales?'Ver reservas activas':'Organizar los próximos eventos'} ${icon('arrow')}</a></div><div class="hero-art">${artwork('castle')}</div><div class="next-event"><div class="eyebrow">${next?'PRÓXIMO EVENTO':'TODO BAJO CONTROL'}</div><h3>${esc(next?.title||'Tu próxima celebración')}</h3>${next?`<div class="meta">${icon('calendar')}${date(next.date)} · ${next.start} – ${next.end}</div><div class="meta">${icon('pin')}${esc(next.address.split(',')[0])}</div><p>${qBadge(next)}</p><button class="text-link" data-action="detail" data-id="${next.id}">Ver detalles del evento ${icon('arrow')}</button>`:'<p>Crea una cotización para comenzar a planificar.</p>'}</div></section>`+
 `<section class="stats">${stat('Reservas activas',events.length,'<span>●</span> Anticipo recibido','calendar')}${stat(sales?'Cotizaciones abiertas':'Eventos por despachar',sales?data.quotes.filter(x=>x.status==='COTIZACION').length:events.filter(x=>x.status!=='DESPACHADA').length,sales?'Pendientes de confirmación':'Preparación y despacho','file')}${stat('Unidades operativas',inventory,'<span>●</span> En el inventario','box')}${stat(sales?'Anticipos recibidos':'Unidades en revisión',sales?money(data.quotes.reduce((n,q)=>n+q.deposit,0)).replace('.00',''):repair,sales?'Acumulado de datos de prueba':'Mantenimiento o daño grave',sales?'chart':'alert')}</section>`+
 `<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>La agenda de la semana</h2><small>02 – 08 noviembre, 2026 · datos de ejemplo</small></div><span class="date-pill">${icon('calendar')} Noviembre</span></div><div class="week">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map((d,i)=>`<div class="day ${i===0?'today':''}">${d}<strong>${i+2}</strong><em style="opacity:${[0,1,2,4].includes(i)?1:0}"></em></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Evento / cliente</th><th>Fecha y horario</th><th>Estado</th><th></th></tr></thead><tbody>${events.slice(0,4).map(eventRow).join('')||'<tr><td colspan="4" class="empty">No hay eventos activos.</td></tr>'}</tbody></table></div><div class="panel-bottom"><span>${events.length} eventos activos en tu agenda</span><a class="text-link" href="#${sales?'reservas':'hojas'}">Ver todos ${icon('arrow')}</a></div></section><section class="panel"><div class="panel-head"><div><h2>Listos para salir</h2><small>El pulso de tu operación</small></div>${icon('box')}</div><div class="readiness">${[['box','Inventario operativo','Unidades listas para reservar',inventory],['out','Despachos pendientes','Eventos confirmados o en preparación',events.filter(q=>q.status!=='DESPACHADA').length],['in','Retornos pendientes','Eventos que ya fueron despachados',events.filter(q=>q.status==='DESPACHADA').length],['alert','En mantenimiento o daño grave','Unidades temporalmente fuera de uso',repair]].map(([ic,t,s,n])=>`<div class="ready-row"><span class="ready-icon">${icon(ic)}</span><div><strong>${t}</strong><small>${s}</small></div><strong class="number">${n}</strong></div>`).join('')}</div><div class="permission-note">${icon('shield')}<span>Estás explorando como <b>${role}</b>. ${role==='Administrador'?'Tienes acceso a todas las áreas.':'Los candados señalan las áreas restringidas.'}</span></div></section></div>`+
 `<div class="activity-grid"><section class="panel"><div class="panel-head"><h2>${role==='Administrador'?'Actividad del equipo':'Tu siguiente paso'}</h2><a class="text-link" href="#${role==='Administrador'?'auditoria':'permisos'}">${role==='Administrador'?'Ver bitácora':'Ver mis permisos'} ${icon('arrow')}</a></div><div class="activity-list">${role==='Administrador'?data.logs.slice(0,3).map(l=>`<div class="activity"><i>${icon('check')}</i><span>${esc(l.message)}</span><small>${esc(l.role)}</small></div>`).join(''):[['check',sales?'Consulta la disponibilidad antes de cotizar.':'Prepara la hoja y asigna animadora y chofer.'],['file',sales?'Registra un anticipo para activar una reserva.':'Registra cada salida y su posterior retorno.'],['shield','Prueba un área con candado para verificar la restricción.']].map(([ic,t])=>`<div class="activity"><i>${icon(ic)}</i><span>${t}</span></div>`).join('')}</div></section><aside class="tip"><div class="eyebrow">UNA BUENA IDEA</div><h3>La magia empieza<br>con una buena planificación.</h3><p>Confirma horarios y disponibilidad para evitar traslapes entre eventos.</p><span class="tip-mark">✳</span></aside></div>`}
function catalog(){return heading('Un catálogo de posibilidades.','Encuentra el recurso ideal para cada celebración.',role==='Administrador'?btn(icon('plus')+' Nuevo producto','new-product'):'')+notice(role==='Ventas'?'Ventas puede consultar el catálogo, comprobar disponibilidad y crear cotizaciones. La edición del inventario está restringida.':role==='Logística'?'Consulta de recursos operativos. Gestiona unidades y su estado desde Productos e inventario.':'Administra el catálogo y consulta su disponibilidad por fecha y horario.')+`<div class="toolbar"><div class="filters">${['Todos',...new Set(data.products.map(p=>p.category))].map(c=>`<button class="filter ${c===category?'active':''}" data-action="filter" data-value="${esc(c)}">${esc(c)}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" placeholder="Buscar en el catálogo…" aria-label="Buscar en el catálogo" value="${esc(search)}"></label></div><div class="catalog-grid" id="catalog-grid">${productCards()}</div>`}
function productCards(){const found=data.products.filter(p=>p.active&&(role!=='Ventas'||p.priceReady)&&(category==='Todos'||p.category===category)&&p.name.toLocaleLowerCase().includes(search.toLocaleLowerCase()));return found.map(p=>`<article class="product"><div class="product-art" style="background:${p.tone}">${badge(p.category,'gray')}${productVisual(p)}</div><div class="product-body"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="product-foot"><div>${role!=='Logística'?`<div class="price">${p.priceReady?money(p.price):'Precio pendiente'} <small>/ evento</small></div>`:`<div class="price">${p.stock-p.maintenance} <small>unidades operativas</small></div>`}<small>${p.stock-p.maintenance} de ${p.stock} unidades operativas</small></div><button class="btn small" data-action="availability" data-id="${p.id}">${icon('calendar')} Disponibilidad</button></div></div></article>`).join('')||'<div class="empty">No encontramos productos con ese nombre.</div>'}
function tablePage(title,sub,heads,rows,action='',note=''){return heading(title,sub,action)+(note?notice(note):'')+`<section class="panel"><div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="empty">Todavía no hay registros en esta sección.</td></tr>`}</tbody></table></div></section>`}
function clientsPage(){return tablePage('Cada celebración tiene una historia.','Gestiona los clientes y sus datos de contacto.',['Cliente','Teléfono','Dirección de instalación','Documentos','Acción'],data.clients.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())).map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)}</small></td><td>${esc(c.phone)}</td><td>${esc(c.address||'Por definir')}</td><td>${data.quotes.filter(q=>q.clientId===c.id).length}</td><td>${btn('Editar cliente','edit-client','small','data-id="'+c.id+'"')}</td></tr>`).join(''),btn(icon('plus')+' Nuevo cliente','new-client'))}
function paymentsPage(){const qs=data.quotes.filter(q=>q.status!=='COTIZACION'),pending=qs.filter(q=>balance(q)>0);return heading('Pagos y saldos pendientes.','Registra abonos o liquida el total, incluso después del despacho o del retorno.')+`<div class="stats">${stat('Por cobrar',money(pending.reduce((n,q)=>n+balance(q),0)),'Saldo restante','chart')}${stat('Órdenes con saldo',pending.length,'Incluye eventos despachados y finalizados','file')}${stat('Pagos recibidos',money(qs.reduce((n,q)=>n+q.deposit,0)),'Anticipos y abonos','check')}</div>`+tablePage('Órdenes y pagos','Las órdenes con saldo aparecen primero. El saldo no bloquea la salida de una reserva confirmada.',['Evento / cliente','Estado de la orden','Total','Pagado','Restante','Acción'],[...pending,...qs.filter(q=>balance(q)===0)].map(q=>`<tr><td><strong>${esc(q.title)}</strong><small>${esc(client(q.clientId).name)} · ${esc(q.id)}</small></td><td>${qBadge(q)}</td><td>${money(q.total)}</td><td>${money(q.deposit)}</td><td>${balance(q)>0?badge(money(balance(q)),'orange'):badge('Pagado completo','green')}</td><td>${btn(balance(q)>0?'Registrar abono':'Ver pagos','payment','small primary','data-id="'+q.id+'"')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Las reservas aparecerán al registrar su anticipo.</td></tr>')}
function openPayment(q){const remaining=balance(q);modal('Pagos de la orden',`<h3>${esc(q.title)}</h3><p>${esc(client(q.clientId).name)}</p><div class="sheet-line"><span>Total</span><strong>${money(q.total)}</strong></div><div class="sheet-line"><span>Pagado</span><strong>${money(q.deposit)}</strong></div><div class="summary-line"><span>Saldo pendiente</span><strong>${money(remaining)}</strong></div><h3>Historial de pagos</h3>${paymentHistory(q).map(p=>`<div class="sheet-line"><span>${esc(p.time==='Registro anterior'?p.time:new Date(p.time).toLocaleString('es-HN'))}<small>${esc(p.note||'Abono')} · ${esc(p.role)}</small></span><strong>${money(p.amount)}</strong></div>`).join('')}${remaining>0?`<div class="fields" style="margin-top:20px">${field('Monto del abono (L)','amount','number',remaining,`required min="0.01" max="${remaining}" step="0.01"`,true)}${field('Observación del pago (opcional)','note','text','','maxlength="250"',true)}</div>${btn('Completar saldo total','fill-balance','small','data-id="'+q.id+'"')}<p class="role-note">Puedes abonar una parte o registrar todo el restante. La orden mantiene su estado operativo.</p>`:notice('Esta orden ya está pagada completamente.')}`,remaining>0?'payment':'',q.id,'Registrar pago')}
function quotesPage(reservations=false){const qs=data.quotes.filter(q=>reservations?q.status!=='COTIZACION':q.status==='COTIZACION');return tablePage(reservations?'Reservas con todo por celebrar.':'De una idea a una gran celebración.',reservations?'El anticipo confirma la reserva y habilita la preparación logística.':'Crea la propuesta y verifica disponibilidad antes de confirmar.',['Evento / cliente','Fecha y horario','Productos','Total / anticipo','Estado','Acción'],qs.map(q=>`<tr><td><strong>${esc(q.title)}</strong><small>${esc(client(q.clientId).name)} · ${esc(q.id)}</small></td><td>${date(q.date)}<small>${q.start} – ${q.end}</small></td><td>${itemSummary(q)}</td><td><strong>${money(q.total)}</strong><small>Pagado: ${money(q.deposit)}</small><small>Saldo: ${money(balance(q))}</small></td><td>${qBadge(q)}</td><td>${q.status==='COTIZACION'?btn('Registrar anticipo','confirm','small','data-id="'+q.id+'"'):btn('Ver detalle','detail','small','data-id="'+q.id+'"')+btn(balance(q)>0?'Registrar abono':'Ver pagos','payment','small','data-id="'+q.id+'"')}</td></tr>`).join(''),btn(icon('plus')+' Nueva cotización','new-quote'),reservations?'El inventario se compromete únicamente al confirmar una reserva. El control de traslapes revisa fecha, horario y unidades disponibles.':'Las cotizaciones no bloquean unidades. Registra un anticipo válido para convertirlas en reservas activas.')}

function productVisual(p){return p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" class="product-photo">`:artwork(p.art)}
function itemSummary(q){return itemsOf(q).map(i=>`<div class="item-summary"><strong>${esc(i.name||product(i.productId).name)}</strong><small>${i.quantity} unidad(es)</small></div>`).join('')}
function inventoryPage(){const archived=inventoryFilter==='archived';return heading('Cada recurso, en su lugar.','Agrega productos, ajusta unidades y controla su estado operativo.',btn(icon('plus')+' Nuevo producto','new-product'))+notice('Puedes agregar o retirar unidades. La baja oculta el producto del catálogo y conserva su historial; puedes reactivarlo después. Los precios los define el Administrador.')+`<div class="filters" style="margin-bottom:18px"><button class="filter ${!archived?'active':''}" data-action="inventory-filter" data-value="active">Productos activos</button><button class="filter ${archived?'active':''}" data-action="inventory-filter" data-value="archived">Dados de baja</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Total</th><th>Operativas</th><th>Fuera de operación</th><th>Acciones</th></tr></thead><tbody>${data.products.filter(p=>archived?!p.active:p.active).map(p=>`<tr><td><div class="inventory-product"><div class="tiny-product">${productVisual(p)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${esc(p.id)}</small>${!p.priceReady?badge('Precio pendiente','orange'):''}</div></div></td><td>${p.stock}</td><td>${badge(p.stock-p.maintenance+' unidades','green')}</td><td>${p.maintenance?badge(p.maintenance+' unidades','orange'):'—'}</td><td><div class="row-actions wrap">${archived?btn('Reactivar','restore-product','small','data-id="'+p.id+'"'):btn('Ajustar unidades','adjust-stock','small','data-id="'+p.id+'"')+btn('Eliminar producto','archive-product','small danger','data-id="'+p.id+'"')+(role==='Administrador'?btn(p.priceReady?'Editar precio':'Definir precio','price','small','data-id="'+p.id+'"'):'')}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay productos en esta vista.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Mantenimiento cotidiano</h2><small>Lavado y reparación menor. No se registran como incidencias.</small></div></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Estado</th><th>Unidades</th><th>Observaciones</th><th>Acción</th></tr></thead><tbody>${data.care.filter(c=>!c.closed).map(c=>`<tr><td>${esc(product(c.productId).name)}</td><td>${badge(c.state,'orange')}</td><td>${c.quantity||1}</td><td class="wrap-cell">${esc(c.note)}</td><td>${btn('Mantenimiento terminado','resolve-care','small','data-id="'+c.id+'"')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay mantenimiento pendiente.</td></tr>'}</tbody></table></div></section>`}

function sheetsPage(){const qs=data.quotes.filter(q=>activeStatus(q.status)||q.status==='FINALIZADA');return tablePage('El plan detrás de la fiesta.','Eventos confirmados, responsables y preparación del despacho.',['Evento','Instalación','Producto','Animadores','Chofer','Estado','Acción'],qs.map(q=>`<tr><td><strong>${esc(q.title)}</strong><small>${date(q.date)} · ${q.start} – ${q.end}</small></td><td>${esc(q.address)}<small>${esc(client(q.clientId).name)}</small></td><td>${itemSummary(q)}</td><td>${assigned(q).animators.map(n=>esc(n)).join('<br>')||'Por asignar'}</td><td>${esc(assigned(q).driver||'Por asignar')}</td><td>${qBadge(q)}</td><td>${['CONFIRMADA','EN_PREPARACION'].includes(q.status)?btn('Preparar hoja','staff','small','data-id="'+q.id+'"'):btn('Ver hoja','detail','small','data-id="'+q.id+'"')}</td></tr>`).join(''),'','Logística ve la información necesaria para preparar, despachar y recibir cada evento. Asigna animadora y chofer antes de registrar una salida.')}
function movementsPage(type){const out=type==='SA',qs=data.quotes.filter(q=>out?['CONFIRMADA','EN_PREPARACION'].includes(q.status):q.status==='DESPACHADA');return heading(out?'Todo listo para salir.':'De vuelta, con todo en orden.',out?'Registra los productos, sus estados y observaciones. Se genera una hoja de salida en PDF.':'Revisa cada producto recibido y genera su hoja de entrada en PDF.')+`<section class="panel"><div class="panel-head"><h2>${out?'Pendientes de despacho':'Pendientes de retorno'}</h2>${badge(qs.length+' eventos','orange')}</div><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Productos / unidades</th><th>Responsables</th><th>Acción</th></tr></thead><tbody>${qs.map(q=>`<tr><td><strong>${esc(q.title)}</strong><small>${date(q.date)} · ${q.start}</small></td><td>${itemSummary(q)}</td><td>${esc(q.staff||'Preparar hoja de evento')}</td><td>${btn(out?'Registrar salida':'Registrar entrada',out?'dispatch':'return','small primary','data-id="'+q.id+'"')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Todo al día. No hay eventos pendientes.</td></tr>'}</tbody></table></div></section><section class="panel" style="margin-top:22px"><div class="panel-head"><div><h2>Historial de ${out?'salidas (SA)':'entradas (EN)'}</h2><small>Cada hoja conserva los estados y observaciones registrados.</small></div></div><div class="table-wrap"><table><thead><tr><th>Movimiento / evento</th><th>Unidades</th><th>Estados registrados</th><th>Fecha</th><th>Hoja</th></tr></thead><tbody>${data.movements.filter(m=>m.type===type).map(m=>`<tr><td><strong>${esc(m.event?.title)}</strong><small>${esc(m.id)}</small></td><td>${m.items.reduce((n,i)=>n+i.quantity,0)}</td><td class="wrap-cell">${[...new Set(m.items.map(i=>i.condition))].map(c=>badge(c,severe(c)?'red':c.startsWith('Requiere')?'orange':'green')).join(' ')}</td><td>${new Date(m.time).toLocaleString('es-HN')}</td><td><div class="row-actions">${btn('Ver hoja','view-movement','small','data-id="'+m.id+'"')}${btn('Descargar PDF','download-pdf','small primary','data-id="'+m.id+'"')}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Las hojas PDF estarán disponibles aquí al registrar un movimiento.</td></tr>'}</tbody></table></div></section>`}
function incidentsPage(){return tablePage('Atención a los daños graves.','Únicamente productos casi inutilizables o inutilizables. El lavado y los daños menores se atienden en Inventario.',['Producto','Observaciones del daño','Estado','Unidades','Acción'],data.incidents.map(i=>`<tr><td><strong>${esc(product(i.productId).name)}</strong><small>${esc(i.id)}</small></td><td class="wrap-cell">${esc(i.note)}</td><td>${badge(i.closed?'Resuelta':i.state,i.closed?'green':'red')}</td><td>${i.quantity||1}</td><td>${!i.closed?btn('Reparación verificada','resolve','small','data-id="'+i.id+'"'):'Completada'}</td></tr>`).join(''),btn(icon('plus')+' Registrar daño grave','new-incident'),'Las incidencias retiran las unidades de disponibilidad. Márcalas disponibles únicamente después de comprobar su reparación.')}
function usersPage(){return tablePage('Un equipo con el acceso correcto.','Cuentas de ejemplo y asignación de los tres roles establecidos.',['Nombre','Rol','Estado','Acción'],data.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.id)}</small></td><td>${esc(u.role)}</td><td>${badge(u.active?'Activo':'Inactivo',u.active?'green':'gray')}</td><td>${u.role==='Administrador'?'<small>Cuenta principal</small>':btn(u.active?'Desactivar':'Activar','toggle-user','small','data-id="'+u.id+'"')}</td></tr>`).join(''),btn(icon('plus')+' Nuevo usuario de ejemplo','new-user'),'Las cuentas son registros de demostración. El selector permite simular cualquier rol para probar flujos; no usa contraseñas ni autentica usuarios reales.')+`<div style="margin-top:22px">${btn(icon('refresh')+' Restablecer datos de ejemplo','reset','danger small')}</div>`}
function reportsPage(){const total=data.quotes.reduce((n,q)=>n+q.total,0),deposits=data.quotes.reduce((n,q)=>n+q.deposit,0);return heading('Una mirada a todo lo que sucede.','Indicadores calculados a partir de los datos de este prototipo.')+`<div class="stats">${stat('Total cotizado',money(total),'Todas las cotizaciones','file')}${stat('Anticipos registrados',money(deposits),'Reservas confirmadas','chart')}${stat('Eventos finalizados',data.quotes.filter(q=>q.status==='FINALIZADA').length,'Con entrada registrada','check')}${stat('Clientes',data.clients.length,'Registrados en el prototipo','users')}</div><div class="split"><section class="panel"><div class="panel-head"><h2>Estado de los eventos</h2></div><div class="report-bars">${['COTIZACION','CONFIRMADA','EN_PREPARACION','DESPACHADA','FINALIZADA'].map(s=>{const count=data.quotes.filter(q=>q.status===s).length;return `<div class="bar-label"><span>${status({status:s})[0]}</span><strong>${count}</strong></div><div class="bar"><div style="width:${count/Math.max(1,data.quotes.length)*100}%"></div></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Resumen operativo</h2></div><div class="sheet">${[['Productos en catálogo',data.products.length],['Unidades totales',data.products.reduce((a,p)=>a+p.stock,0)],['Unidades fuera de operación',data.products.reduce((a,p)=>a+p.maintenance,0)],['Movimientos registrados',data.movements.length],['Incidencias abiertas',data.incidents.filter(i=>!i.closed).length]].map(([l,v])=>`<div class="sheet-line"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div></section></div>`}
function auditPage(){return tablePage('Cada paso deja un registro.','Bitácora de operaciones realizadas con los roles de prueba.',['Operación','Rol','Momento'],data.logs.map(l=>`<tr><td>${esc(l.message)}</td><td>${esc(l.role)}</td><td>${l.time==='Datos de ejemplo'?l.time:new Date(l.time).toLocaleString('es-HN')}</td></tr>`).join(''))}
function permissionsPage(){return heading('Tres roles. Un equipo coordinado.','Cambia de rol y prueba qué puede consultar o gestionar cada área.')+notice('Simulación de permisos con datos de ejemplo guardados en este navegador. El acceso al sitio es privado. Para una aplicación real, la autorización se debe aplicar también en el servidor.','demo')+`<div class="test-cards">${ROLES.map(r=>`<article class="test-card ${r===role?'active':''}"><h3>${icon(r==='Administrador'?'shield':r==='Ventas'?'file':'box')} ${r}</h3><p>${r==='Administrador'?'Acceso total a las áreas comerciales, operativas y de administración.':r==='Ventas'?'Consulta catálogo y disponibilidad. Gestiona clientes, cotizaciones y reservas.':'Gestiona inventario operativo, hojas de eventos, salidas, entradas e incidencias.'}</p><button class="btn small ${r===role?'':'primary'}" data-action="role" data-value="${r}">${r===role?'Rol actual':'Usar este rol'}</button></article>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Comprobar un acceso</h2><small>Las rutas se validan también cuando abres un enlace directo.</small></div>${badge(role,'green')}</div><div class="test-box"><label>Área que quieres intentar abrir<select id="test-area">${AREAS.filter(x=>!['inicio','permisos'].includes(x[0])).map(([id,n])=>`<option value="${id}" ${id==='usuarios'?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn primary" data-action="test-access">${icon('key')} Intentar acceso</button></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Matriz de permisos</h2><small>La columna resaltada corresponde al rol activo.</small></div>${icon('shield')}</div><div class="table-wrap"><table class="matrix"><thead><tr><th>Área del sistema</th>${ROLES.map(r=>`<th class="${role===r?'col-active':''}">${r}</th>`).join('')}</tr></thead><tbody>${AREAS.filter(x=>!['inicio','permisos'].includes(x[0])).map(([id,n])=>`<tr><td>${n}</td>${ROLES.map(r=>`<td class="${role===r?'col-active':''}"><span class="${allowed(r,id)?'yes':'no'}">${icon(allowed(r,id)?'check':'lock')}${permissionLabel(r,id)}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function denied(){const title=AREAS.find(x=>x[0]===route)?.[1]||route;return `<section class="blocked-box"><div class="blocked-icon">${icon('lock')}</div><div class="eyebrow">ACCESO RESTRINGIDO</div><h1>Esta área requiere otro permiso.</h1><p>Intentaste abrir <b>${esc(title)}</b> como <b>${role}</b>.<br>Tu rol no tiene acceso a esta sección. La ruta quedó bloqueada y no se ha realizado ninguna operación.</p><div class="sheet-actions" style="justify-content:center"><a class="btn primary" href="#inicio">Volver al resumen</a><a class="btn" href="#permisos">Ver mis permisos ${icon('arrow')}</a></div><p style="font-size:11px;margin:23px 0 0">Usa “Simular rol” en la barra superior para probar otro perfil.</p></section>`}
function login(){return `<div class="sign-in"><div class="login-intro"><div class="login-emblem"><span class="brandmark">✳</span><h2 style="margin:0">El Club de Pon Pon.</h2></div><div class="eyebrow">BIENVENIDO AL PROTOTIPO PRIVADO</div><h1>Elige cómo quieres explorar.</h1><p>Prueba los flujos de cada equipo y comprueba sus permisos con datos de ejemplo. No necesitas una contraseña.</p></div><div class="test-cards">${ROLES.map(r=>`<article class="test-card"><h3>${r}</h3><p>${r==='Administrador'?'Gestiona todas las áreas del sistema.':r==='Ventas'?'Catálogo, clientes, cotizaciones y reservas.':'Inventario, hojas, despacho, retorno e incidencias.'}</p><button class="btn primary" data-action="role" data-value="${r}">Entrar como ${r}</button></article>`).join('')}</div></div>`}
function render(){nav();header();if(!role){$('#topbar').innerHTML='<div class="breadcrumb"><strong>El Club de Pon Pon</strong></div><span class="private" style="margin-left:auto">'+icon('lock')+' Acceso privado</span>';$('#sidebar').style.display='none';$('.workspace').style.cssText='margin-left:0;width:100%';$('#main').innerHTML=login();return}$('#sidebar').style.display='';$('.workspace').style.cssText='';const pages={inicio:dashboard,catalogo:catalog,clientes:clientsPage,cotizaciones:()=>quotesPage(false),reservas:()=>quotesPage(true),pagos:paymentsPage,productos:inventoryPage,hojas:sheetsPage,salidas:()=>movementsPage('SA'),entradas:()=>movementsPage('EN'),incidencias:incidentsPage,usuarios:usersPage,reportes:reportsPage,auditoria:auditPage,permisos:permissionsPage};$('#main').innerHTML=!AREAS.some(x=>x[0]===route)?heading('No encontramos esta página.','Vuelve al resumen desde la navegación.')+'<a class="btn primary" href="#inicio">Ir al resumen</a>':!allowed(role,route)?denied():pages[route]();document.title=(AREAS.find(x=>x[0]===route)?.[1]||'Acceso')+' · Pon Pon'}
function field(label,name,type='text',value='',extra='',full=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,opts,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${opts}</select></label>`}
const options=(items,valueKey='id',nameKey='name',selected='')=>items.map(x=>`<option value="${esc(x[valueKey])}" ${x[valueKey]===selected?'selected':''}>${esc(x[nameKey])}</option>`).join('');
function modal(title,html,type='',id='',submit='Guardar'){if(documentUrl)URL.revokeObjectURL(documentUrl);documentUrl='';productImage='';$('#modal').classList.toggle('wide',['quote','dispatch','return','movement-view'].includes(type));modalType=type;modalId=id;$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Cerrar ventana">${icon('close')}</button></div><form id="modal-form" class="modal-body">${html}<div class="form-error" id="form-error" role="alert"></div><div class="modal-foot">${btn(type?'Cancelar':'Cerrar','close','')} ${type&&type!=='movement-view'?`<button class="btn primary" type="submit">${submit}</button>`:''}</div></form>`;$('#modal').showModal()}
function animatorField(name){return `<div class="animator-row"><label class="field">Nombre del animador<input name="animator" value="${esc(name)}" required maxlength="100"></label>${btn('Quitar','remove-animator','small')}</div>`}
function openNewQuote(selected=''){
 if(!allowed(role,'cotizaciones',true))return toast('Acceso denegado: no puedes crear cotizaciones.');
 const choices=data.products.filter(p=>p.active&&p.priceReady);quoteDraft=selected&&choices.some(p=>p.id===selected)?[{productId:selected,quantity:1}]:[];
 modal('Nueva cotización',`<div class="fields">${field('Nombre del evento','title','text','','required maxlength="100"',true)}${selectField('Cliente','clientId',options(data.clients))}${field('Fecha del evento','date','date','2026-11-07','required')}${field('Hora de inicio','start','time','14:00','required')}${field('Hora de finalización','end','time','18:00','required')}${field('Dirección de instalación (opcional)','address','text','','maxlength="180"',true)}</div><div class="quote-builder"><h3>Productos de la cotización</h3><p class="muted">Busca y añade productos desde el catálogo visual.</p><div class="picker-controls">${field('Buscar productos','quoteSearch','search','','placeholder="Nombre o descripción"')}${selectField('Categoría','quoteCategory','<option value="Todos">Todas las categorías</option>'+[...new Set(choices.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join(''))}</div><div id="quote-catalog" class="quote-catalog"></div><div id="quote-lines" aria-live="polite"></div></div><div class="summary-line"><span id="quote-count">Total de la cotización</span><strong id="quote-total"></strong></div><p class="role-note">El total incluye todos los productos. El anticipo activa la reserva tras verificar la disponibilidad de cada uno.</p>`,'quote','','Crear cotización');renderQuoteCatalog();renderQuoteLines();
}
function renderQuoteCatalog(){const f=$('#modal-form'),term=f.elements.quoteSearch.value.toLocaleLowerCase(),cat=f.elements.quoteCategory.value;const choices=data.products.filter(p=>p.active&&p.priceReady&&(cat==='Todos'||p.category===cat)&&(p.name+' '+p.description).toLocaleLowerCase().includes(term));$('#quote-catalog').innerHTML=choices.map(p=>`<article class="quote-product-card"><div class="quote-card-image" style="background:${p.tone}">${productVisual(p)}</div><div class="quote-card-body"><small>${esc(p.category)}</small><h3>${esc(p.name)}</h3><strong>${money(p.price)}</strong><p>${p.stock-p.maintenance} unidades operativas</p>${btn('Añadir a cotización','add-quote-item','small primary','data-id="'+p.id+'" aria-label="Añadir '+esc(p.name)+'"')}</div></article>`).join('')||'<p class="empty">No hay productos que coincidan con tu búsqueda.</p>'}
function renderQuoteLines(){if(!$('#quote-lines'))return;$('#quote-lines').innerHTML=quoteDraft.length?`<div class="selected-heading"><strong>Productos añadidos</strong><span>${quoteDraft.length} productos</span></div>`+quoteDraft.map((i,k)=>{const p=product(i.productId);return `<div class="quote-line"><div class="tiny-product">${productVisual(p)}</div><div class="quote-line-name"><strong>${esc(p.name)}</strong><small>${money(p.price)} / unidad</small></div><label class="field">Cantidad<input aria-label="Cantidad de ${esc(p.name)}" data-quote-index="${k}" type="number" value="${i.quantity}" min="1" step="1" required></label><strong id="subtotal-${k}">${money(p.price*i.quantity)}</strong><button type="button" class="icon-button" data-action="remove-quote-item" data-index="${k}" aria-label="Quitar ${esc(p.name)}">${icon('close')}</button></div>`}).join(''):'<div class="empty compact">Aún no has añadido productos. Puedes incluir varios en esta cotización.</div>';updateQuoteTotal()}
function updateQuoteTotal(){if(!$('#quote-total'))return;$('#quote-total').textContent=money(quoteDraft.reduce((n,i)=>n+product(i.productId).price*(i.quantity||0),0));$('#quote-count').textContent=`Total · ${quoteDraft.reduce((n,i)=>n+(i.quantity||0),0)} unidad(es)`;quoteDraft.forEach((i,k)=>{if($('#subtotal-'+k))$('#subtotal-'+k).textContent=money(product(i.productId).price*(i.quantity||0))})}
function detail(id){const q=data.quotes.find(x=>x.id===id);if(!q)return;modal(role==='Logística'?'Hoja de evento':'Detalle del evento',`<h2>${esc(q.title)}</h2><p class="muted" style="font-size:12px">${esc(q.id)} · ${esc(client(q.clientId).name)}</p>${qBadge(q)}<div class="step-line"><span>1. Cotización</span> → <span>2. Reserva</span> → <span>3. Salida / entrada</span></div>${[['Fecha y horario',date(q.date)+' · '+q.start+' – '+q.end],['Instalación',q.address],['Animadores',assigned(q).animators.join(', ')||'Por asignar'],['Chofer',assigned(q).driver||'Por asignar']].map(([l,v])=>`<div class="sheet-line"><span>${l}</span><strong style="text-align:right;max-width:65%">${esc(v)}</strong></div>`).join('')}<h3 style="margin-top:24px">Productos incluidos</h3>${itemsOf(q).map(i=>`<div class="quote-line detail-line"><div class="tiny-product">${productVisual(product(i.productId))}</div><div class="quote-line-name"><strong>${esc(i.name)}</strong><small>${i.quantity} unidad(es)</small></div>${role!=='Logística'?`<strong>${money(i.unitPrice*i.quantity)}</strong>`:''}</div>`).join('')}${role!=='Logística'?[['Total',money(q.total)],['Pagado',money(q.deposit)],['Saldo',money(q.total-q.deposit)]].map(([l,v])=>`<div class="sheet-line"><span>${l}</span><strong>${v}</strong></div>`).join(''):''}`)}
function incidentModal(id=''){if(!allowed(role,'incidencias',true))return toast('Acceso denegado.');modal('Registrar daño grave',`<p class="muted">Usa incidencias únicamente cuando el producto sea casi inutilizable o inutilizable.</p><div class="fields">${selectField('Producto','productId',options(data.products.filter(p=>p.active),'id','name',id),true)}${field('Unidades afectadas','quantity','number',1,'required min="1" step="1"')}${selectField('Gravedad','state','<option>Daño grave (casi inutilizable)</option><option>Inutilizable</option>')}<label class="field full">Observaciones del daño<textarea name="note" required maxlength="300"></textarea></label></div>`,'incident')}
function newProductModal(){if(!allowed(role,'productos',true))throw Error('Acceso denegado.');modal('Nuevo producto',`<div class="fields">${field('Nombre del producto','name','text','','required maxlength="100"',true)}${selectField('Categoría','category',['Inflables','Mobiliario','Juegos','Personal','Decoración'].map(c=>`<option>${c}</option>`).join(''))}${field('Unidades totales','stock','number',1,'min="1" step="1" required')}${role==='Administrador'?field('Precio de alquiler (L)','price','number','','required min="0" step="0.01"',true):'<div class="field full"><small>El Administrador definirá el precio antes de habilitar este producto para Ventas.</small></div>'}${field('Descripción','description','text','','maxlength="180"',true)}<label class="field full">Imagen del producto (opcional)<input id="product-image" type="file" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG o WebP, hasta 5 MB. Se mostrará en el catálogo y la cotización.</small></label><div class="field full" id="product-image-preview"></div></div>`,'product','','Crear producto')}
let imageLoading=false;
async function loadProductImage(file){productImage='';if(!file){$('#product-image-preview').innerHTML='';return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Selecciona una imagen JPG, PNG o WebP de hasta 5 MB.');imageLoading=true;try{const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,700/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);productImage=canvas.toDataURL('image/jpeg',.8);$('#product-image-preview').innerHTML=`<img class="upload-preview" src="${productImage}" alt="Vista previa del nuevo producto">`;}finally{imageLoading=false}}
function openInspection(q,out){if(!allowed(role,out?'salidas':'entradas',true))throw Error('Acceso denegado.');const departure=data.movements.find(m=>m.quoteId===q.id&&m.type==='SA');inspectionDraft=itemsOf(q).map(i=>({productId:i.productId,quantity:i.quantity,condition:'',note:'',departureCondition:departure?[...new Set(departure.items.filter(d=>d.productId===i.productId).map(d=>d.condition))].join(' / '):''}));modal(out?'Registrar salida y generar hoja':'Registrar entrada y generar hoja',`<h3>${esc(q.title)}</h3><p class="muted">${unitsOf(q)} unidad(es) · ${esc(q.staff||'Asigna responsables en la hoja de eventos')}</p>${notice(out?'Verifica el estado de cada producto antes del despacho.':'Registra el estado al regresar. Solo el daño grave o inutilizable genera una incidencia.')}<div class="inspection-toolbar"><small>Separa unidades si tienen estados diferentes.</small>${btn('Todos en buen estado','all-good','small')}</div><div id="inspection-list"></div><label class="field full" style="margin-top:20px">Observaciones generales<textarea name="note" maxlength="600" placeholder="Entrega, recepción, faltantes o cualquier detalle adicional"></textarea></label><p class="role-note">Se guardarán las observaciones y se generará una hoja PDF. También podrás descargarla desde el historial.</p>`,out?'dispatch':'return',q.id,out?'Registrar salida y PDF':'Registrar entrada y PDF');renderInspection()}
function readInspection(){const form=$('#modal-form');return inspectionDraft.map((i,k)=>({...i,condition:form.elements['condition'+k]?.value||'',note:form.elements['lineNote'+k]?.value||''}))}
function renderInspection(){const out=modalType==='dispatch';$('#inspection-list').innerHTML=inspectionDraft.map((i,k)=>{const p=product(i.productId);return `<section class="inspection-row"><div class="inspection-product"><div class="tiny-product">${productVisual(p)}</div><div><h3>${esc(p.name)}</h3><small>${i.quantity} unidad(es) · Grupo ${k+1}</small></div>${i.quantity>1?btn('Separar una unidad','split-inspection','small','data-index="'+k+'"'):''}</div>${!out?`<p class="departure-state">Estado(s) al salir: <b>${esc(i.departureCondition||'No registrado')}</b></p>`:''}<div class="fields">${selectField(out?'Estado al salir':'Estado al entrar','condition'+k,'<option value="">Selecciona el estado…</option>'+(out?OUT_CONDITIONS:IN_CONDITIONS).map(c=>`<option ${c===i.condition?'selected':''}>${c}</option>`).join(''),true)}<label class="field full">Observaciones de ${esc(p.name)} · grupo ${k+1}<textarea name="lineNote${k}" maxlength="300" ${severe(i.condition)?'required':''} placeholder="Describe desgaste, limpieza o detalles del producto">${esc(i.note)}</textarea></label></div><div class="severe-warning" id="severity-${k}" ${severe(i.condition)?'':'hidden'}>Se generará una incidencia grave. Describe el daño en las observaciones.</div></section>`}).join('');inspectionDraft.forEach((_,k)=>$('#modal-form').elements['condition'+k].required=true)}
function getMovement(id){const m=data.movements.find(x=>x.id===id);if(!m||!allowed(role,m.type==='SA'?'salidas':'entradas'))throw Error('Acceso denegado a esta hoja.');return m}
function viewMovement(id){const m=getMovement(id),out=m.type==='SA';modal(out?'Hoja de salida':'Hoja de entrada',`<div class="document-summary"><div><h3>${esc(m.event.title)}</h3><small>${esc(m.id)} · ${new Date(m.time).toLocaleString('es-HN')}</small></div><a class="btn primary" id="pdf-file-link" download>Descargar PDF</a></div><p>${esc(m.event.client)}<br><small>${esc(m.event.address)}<br>Responsables: ${esc(m.event.staff)}</small></p>${m.items.map(i=>`<section class="inspection-row"><h3>${esc(i.name)} <small>· ${i.quantity} unidad(es)</small></h3>${!out?`<p>Estado(s) al salir: <b>${esc(i.departureCondition||'No registrado')}</b></p>`:''}<p>Estado al ${out?'salir':'entrar'}: ${badge(i.condition,severe(i.condition)?'red':i.condition.startsWith('Requiere')?'orange':'green')}</p><p><b>Observaciones:</b> ${esc(i.note||'Sin observaciones.')}</p></section>`).join('')}<h3>Observaciones generales</h3><p class="wrap-cell">${esc(m.note||'Sin observaciones generales.')}</p><div class="summary-line"><span>Unidades ${out?'entregadas':'recibidas'}</span><strong>${m.quantity}</strong></div>`,'movement-view',id);const file=movementDownload(m);documentUrl=file.url;$('#pdf-file-link').href=file.url;$('#pdf-file-link').download=file.filename;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,q=data.quotes.find(x=>x.id===id);try{
 if(a==='menu')$('#sidebar').classList.toggle('open');if(a==='close')$('#modal').close();if(a==='nav')go(el.dataset.to);if(a==='role')setRole(el.dataset.value);if(a==='logout'){role='';sessionStorage.setItem('ponpon-role','signed-out');render()}
 if(a==='filter'){category=el.dataset.value;render()}if(a==='inventory-filter'){inventoryFilter=el.dataset.value;render()}if(a==='new-quote')openNewQuote();if(a==='detail')detail(id);
 if(a==='add-quote-item'){const p=product(id),quantity=1;if(!p.id||!Number.isInteger(quantity)||quantity<1)throw Error('Elige un producto y una cantidad entera mayor a cero.');const previous=quoteDraft.find(i=>i.productId===p.id);if((previous?.quantity||0)+quantity>p.stock-p.maintenance)throw Error('La cantidad supera las unidades operativas de '+p.name+'.');if(previous)previous.quantity+=quantity;else quoteDraft.push({productId:p.id,quantity});renderQuoteLines();$('#form-error').textContent='';}
 if(a==='remove-quote-item'){quoteDraft.splice(Number(el.dataset.index),1);renderQuoteLines()}
 if(a==='payment'){if(!allowed(role,'pagos',true))throw Error('Acceso denegado.');openPayment(q)}
 if(a==='fill-balance')$('#modal-form').elements.amount.value=balance(q);
 if(a==='edit-client'){if(!allowed(role,'clientes',true))throw Error('Acceso denegado.');const c=client(id);modal('Editar cliente',`<div class="fields">${field('Nombre completo','name','text',c.name,'required maxlength="120"',true)}${field('Teléfono','phone','tel',c.phone,'required maxlength="30"',true)}${field('Dirección de instalación','address','text',c.address||'','maxlength="180"',true)}</div><p class="role-note">Se actualizan los datos de contacto. Las direcciones de eventos ya registrados se conservan.</p>`,'editClient',id,'Guardar cambios')}
 if(a==='new-client')modal('Nuevo cliente',`<div class="fields">${field('Nombre completo','name','text','','required maxlength="120"',true)}${field('Teléfono','phone','tel','','required maxlength="30"',true)}${field('Dirección de instalación','address','text','','maxlength="180"',true)}</div>`,'client','','Registrar cliente');
 if(a==='new-product')newProductModal();
 if(a==='price'){if(role!=='Administrador')throw Error('Acceso denegado.');const p=product(id);modal('Definir precio',`<h3>${esc(p.name)}</h3><div class="fields">${field('Precio de alquiler (L)','price','number',p.price,'required min="0" step="0.01"',true)}</div><p class="role-note">Este precio se usará en las nuevas cotizaciones.</p>`,'price',id,'Guardar precio')}
 if(a==='adjust-stock'){if(!allowed(role,'productos',true))throw Error('Acceso denegado.');const p=product(id);modal('Ajustar unidades',`<h3>${esc(p.name)}</h3><p class="muted">Existencia actual: ${p.stock} unidades.</p><div class="fields">${selectField('Operación','direction','<option value="add">Agregar unidades</option><option value="remove">Retirar unidades</option>')}${field('Cantidad','quantity','number',1,'required min="1" step="1"')}<label class="field full">Motivo / observaciones<textarea name="note" maxlength="300" required></textarea></label></div>`,'adjustStock',id,'Guardar ajuste')}
 if(a==='archive-product'){if(!allowed(role,'productos',true))throw Error('Acceso denegado.');modal('Eliminar producto del catálogo',`<p><b>${esc(product(id).name)}</b> dejará de aparecer en el catálogo de nuevas cotizaciones.</p><p class="muted">Se conserva su historial. Podrás reactivarlo desde “Dados de baja”. Si tiene reservas o mantenimiento pendiente, primero tendrás que resolverlos.</p>${field('Motivo de eliminación','note','text','','required maxlength="250"',true)}<p class="role-note">Se registrará el producto, el motivo, la fecha y el rol en la bitácora.</p>`,'archiveProduct',id,'Eliminar producto')}
 if(a==='restore-product'){run('restoreProduct',{id});render();toast('Producto reactivado.')}
 if(a==='confirm'){if(!allowed(role,'reservas',true))throw Error('Acceso denegado.');modal('Registrar anticipo',`<p>Evento: <b>${esc(q.title)}</b></p><p class="muted">${itemsOf(q).length} productos · ${unitsOf(q)} unidad(es)</p><div class="summary-line"><span>Total</span><strong>${money(q.total)}</strong></div><div class="fields" style="margin-top:20px">${field('Anticipo o pago completo (L)','deposit','number',q.total/2,`required min="0.01" max="${q.total}" step="0.01"`,true)}</div><p class="role-note">Se verifica la disponibilidad de todos los productos antes de confirmar.</p>`,'confirm',id,'Confirmar reserva')}
 if(a==='staff'){if(!allowed(role,'hojas',true))throw Error('Acceso denegado.');const team=assigned(q);modal('Preparar hoja de evento',`<p><b>${esc(q.title)}</b><br><small>${date(q.date)} · ${q.start} – ${q.end}</small></p>${itemSummary(q)}<h3>Animadores asignados</h3><div id="animator-fields">${(team.animators.length?team.animators:['']).map(n=>animatorField(n)).join('')}</div>${btn('Añadir otro animador','add-animator','small')}<div class="fields" style="margin-top:20px">${field('Chofer asignado','driver','text',team.driver,'required maxlength="100"',true)}</div><p class="role-note">Cada animador se registra por separado. El chofer tiene su propia asignación.</p>`,'staff',id,'Guardar hoja')}
 if(a==='add-animator')$('#animator-fields').insertAdjacentHTML('beforeend',animatorField(''));
 if(a==='remove-animator')e.target.closest('.animator-row').remove();
 if(a==='dispatch'||a==='return')openInspection(q,a==='dispatch');
 if(a==='all-good'){inspectionDraft=readInspection().map(i=>({...i,condition:'Buen estado'}));renderInspection()}
 if(a==='split-inspection'){inspectionDraft=readInspection();const k=Number(el.dataset.index),i=inspectionDraft[k];if(i.quantity>1){i.quantity--;inspectionDraft.splice(k+1,0,{...i,quantity:1});renderInspection()}}
 if(a==='download-pdf')downloadMovement(getMovement(id));if(a==='view-movement')viewMovement(id);
 if(a==='new-incident')incidentModal(id);if(a==='resolve'||a==='resolve-care'){if(!allowed(role,a==='resolve'?'incidencias':'productos',true))throw Error('Acceso denegado.');modal(a==='resolve'?'Verificar reparación del daño grave':'Finalizar mantenimiento',`<p>${a==='resolve'?'Confirma que el daño grave fue reparado y que las unidades son seguras y funcionales.':'Confirma que el lavado o la reparación menor ha finalizado.'} Las unidades volverán a estar operativas.</p>`,a==='resolve'?'resolve':'resolveCare',id,'Confirmar disponibilidad')}
 if(a==='new-user'){if(role!=='Administrador')throw Error('Acceso denegado.');modal('Nuevo usuario de ejemplo',`<div class="fields">${field('Nombre','name','text','','required maxlength="100"',true)}${selectField('Rol asignado','role',ROLES.map(r=>`<option>${r}</option>`).join(''),true)}</div><p class="role-note">Registro de demostración. No crea una cuenta real ni envía invitaciones.</p>`,'user')}
 if(a==='toggle-user'){run('toggleUser',{id});render();toast('Estado del usuario actualizado.')}
 if(a==='reset'){if(role!=='Administrador')throw Error('Acceso denegado.');modal('Restablecer los datos de ejemplo','<p>Se borrarán las operaciones de prueba realizadas en este navegador y se recuperará el escenario inicial.</p>','reset','','Restablecer datos')}
 if(a==='test-access'){const area=$('#test-area').value;go(area);toast(allowed(role,area)?'Acceso permitido para '+role+'.':'Acceso bloqueado para '+role+'.')}
 if(a==='availability'){const p=product(id);modal('Consultar disponibilidad',`<h3>${esc(p.name)}</h3><div class="fields" style="margin-top:20px">${field('Fecha del evento','date','date','2026-11-03','required',true)}${field('Inicio','start','time','14:00','required')}${field('Finalización','end','time','18:00','required')}</div><div class="summary-line" id="availability-result"><span>Selecciona fecha y horario</span></div>${allowed(role,'cotizaciones',true)&&p.priceReady?`<div style="margin-top:15px">${btn('Crear cotización con este producto','quote-product','small','data-id="'+p.id+'"')}</div>`:''}`,'availability',id,'Consultar');updateAvailability()}
 if(a==='quote-product'){const form=$('#modal-form'),values={date:form.elements.date.value,start:form.elements.start.value,end:form.elements.end.value};$('#modal').close();openNewQuote(id);Object.entries(values).forEach(([k,v])=>$('#modal-form').elements[k].value=v)}
 if(a==='activity')modal('Actividad reciente',role==='Administrador'?`<div class="activity-list">${data.logs.slice(0,6).map(l=>`<div class="activity"><span>${esc(l.message)}</span><small>${esc(l.role)}</small></div>`).join('')}</div>`:`<p>Estás trabajando como <b>${role}</b>. Consulta tus áreas desde “Probar permisos”.</p><a class="btn small" href="#permisos" data-action="close">Ver mis permisos</a>`);
 }catch(err){if($('#modal').open&&$('#form-error'))$('#form-error').textContent=err.message;else toast(err.message)}});
function updateAvailability(){const f=$('#modal-form');if(!$('#availability-result'))return;const {date:d,start:s,end:e}=Object.fromEntries(new FormData(f));const valid=d&&s&&e&&e>s;$('#availability-result').innerHTML=valid?`<span>Unidades libres en este horario</span><strong>${freeUnits(data,modalId,d,s,e)} de ${product(modalId).stock}</strong>`:'<span>Selecciona una fecha y un horario válido.</span>'}
document.addEventListener('change',async e=>{try{if(e.target.id==='role')setRole(e.target.value);if(e.target.closest('#modal-form')){if(modalType==='quote'&&e.target.name==='quoteCategory')renderQuoteCatalog();if(modalType==='availability')updateAvailability();if(e.target.id==='product-image')await loadProductImage(e.target.files[0]);if(['dispatch','return'].includes(modalType)&&e.target.name.startsWith('condition')){const k=Number(e.target.name.slice(9));$('#severity-'+k).hidden=!severe(e.target.value);$('#modal-form').elements['lineNote'+k].required=severe(e.target.value)}}}catch(err){if($('#form-error'))$('#form-error').textContent=err.message}});
document.addEventListener('input',e=>{if(modalType==='quote'&&e.target.name==='quoteSearch')renderQuoteCatalog();if(e.target.id==='search'){search=e.target.value;$('#catalog-grid').innerHTML=productCards()}if(e.target.dataset.quoteIndex!==undefined&&modalType==='quote'){quoteDraft[Number(e.target.dataset.quoteIndex)].quantity=Number(e.target.value);updateQuoteTotal()}});
document.addEventListener('submit',e=>{if(e.target.id!=='modal-form')return;e.preventDefault();const kind=modalType,payload={...Object.fromEntries(new FormData(e.target)),...(modalId?{id:modalId}:{})};try{if(kind==='availability'){updateAvailability();return}if(!kind||kind==='movement-view')return;if(kind==='staff')payload.animators=new FormData(e.target).getAll('animator');if(kind==='quote')payload.items=quoteDraft;if(kind==='dispatch'||kind==='return')payload.items=readInspection();if(kind==='product'){if(imageLoading)throw Error('Espera a que termine de cargar la imagen.');payload.image=productImage}if(kind==='adjustStock')payload.delta=Number(payload.quantity)*(payload.direction==='remove'?-1:1);const result=run(kind,payload);$('#modal').close();if(kind==='quote')go('cotizaciones');else if(kind==='confirm')go('pagos');else render();if(kind==='dispatch'||kind==='return')downloadMovement(result);toast({payment:'Pago registrado y saldo actualizado.',editClient:'Datos del cliente actualizados.',quote:'Cotización creada con todos los productos.',confirm:'Reserva confirmada. Ya está disponible para Logística.',dispatch:'Salida registrada. Hoja PDF generada.',return:'Entrada registrada. Hoja PDF generada.',staff:'Hoja preparada y responsables asignados.',reset:'Escenario inicial restablecido.',archiveProduct:'Producto dado de baja. Su historial se conserva.',product:role==='Logística'?'Producto agregado. Falta que el Administrador defina su precio.':'Producto agregado al inventario.'}[kind]||'Los cambios se guardaron correctamente.')}catch(err){$('#form-error').textContent=err.name==='QuotaExceededError'?'No hay espacio suficiente en este navegador. Usa una imagen más pequeña. No se guardaron los cambios.':err.message}});
document.addEventListener('click',e=>{if(e.target.closest('.nav')){$('#sidebar').classList.remove('open');if($('#modal').open)$('#modal').close()}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'inicio';search='';category='Todos';render();window.scrollTo(0,0)});
render();
